  'person',
  '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","locale":"en","product_id":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","seo":{"pageTitle":"Gapyeong Day Tour from Seoul — Nami Island, Garden of Morning Calm & Petite France | AtoC Korea","metaDescription":"Join-in group coach day tour from Seoul to Gapyeong: Nami Island''s metasequoia avenue, the Garden of Morning Calm, and Petite France. All three admissions included. Hongik University or Myeongdong pickup, back in Seoul by 19:00.","title":"Gapyeong Day Tour from Seoul — Nami Island, Morning Calm & Petite France","description":"Three Gapyeong landmarks in one 11.5-hour coach day from Seoul, with Nami Island ferry, Garden of Morning Calm and Petite France admissions all included.","primaryKeywords":["Gapyeong day tour from Seoul","Nami Island tour","Garden of Morning Calm tour","Petite France Gapyeong","Seoul day trip Nami Island Morning Calm"],"ogImage":"https://www.atockorea.com/images/tours/nami-island/nami-metasequoia-sunset-lake.webp"},"catalog_card":{"slug":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","title":"Gapyeong Day Tour from Seoul: Nami Island, Garden of Morning Calm & Petite France","subtitle":"The Gapyeong trio in one coach day — no mountain hike, three admissions included","region":"Seoul → Gyeonggi-do (Gapyeong)","duration":"11.5 hours","stopsCount":3,"rating":0,"reviewCount":0,"badges":["Day trip from Seoul","Gapyeong","Join-in group","K-drama","Gardens"],"tags":["Day trip from Seoul","Gapyeong","Join-in group","K-drama","Gardens","Family friendly"],"heroImage":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","thumbnail":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","priceLabel":"","shortCardDescription":"Seoul''s easiest countryside day: Nami Island''s metasequoia avenue, a 330,000 m² themed arboretum, and a Little Prince village — all three admissions included, back in Seoul by 19:00."},"headlineLine1":"Seoul Day Tour","headlineLine2":"Nami, Morning Calm & Petite France","price":{"amountLabel":"59","currency":"USD","per":"person","salePriceUsd":59},"hero":{"imageUrl":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","imagePosition":"center 45%","images":["/images/tours/nami-island/nami-metasequoia-sunset-lake.webp"],"tagline":"Gapyeong''s three signature stops in one relaxed coach day from Seoul — a tree-lined river island, Korea''s best-known private garden, and a licensed Le Petit Prince village","pills":["Day trip from Seoul","Gardens + Hallyu","All admissions included"],"meta":{"duration":"11.5 hours","region":"Seoul → Gyeonggi-do (Gapyeong)","stops":"3 stops","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"Overview"},{"id":"itinerary","label":"Itinerary"},{"id":"details","label":"Details"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"Reviews"}],"glanceItems":[{"icon":"clock","label":"Duration","value":"11.5 hours"},{"icon":"camera","label":"Photo Potential","value":"Very High","level":5},{"icon":"mountain","label":"Scenery","value":"High","level":4},{"icon":"footprints","label":"Walking","value":"Easy to Moderate","level":2},{"icon":"cloud-rain","label":"Rain Suitability","value":"Moderate","level":3},{"icon":"users","label":"Family Suitability","value":"Very Good","level":5},{"icon":"gauge","label":"Pace","value":"Relaxed","level":3}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"Nami Island (Namiseom)","caption":"Nami Island (Namiseom) — photo 1","alt":"Nami Island (Namiseom) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"Nami Island (Namiseom)","caption":"Nami Island (Namiseom) — photo 2","alt":"Nami Island (Namiseom) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"Nami Island (Namiseom)","caption":"Nami Island (Namiseom) — photo 3","alt":"Nami Island (Namiseom) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"Nami Island (Namiseom)","caption":"Nami Island (Namiseom) — photo 4","alt":"Nami Island (Namiseom) — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 1","alt":"The Garden of Morning Calm — gallery image 1"},{"id":6,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 2","alt":"The Garden of Morning Calm — gallery image 2"},{"id":7,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 3","alt":"The Garden of Morning Calm — gallery image 3"},{"id":8,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 4","alt":"The Garden of Morning Calm — gallery image 4"},{"id":9,"type":"photo","src":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","location":"Petite France","caption":"Petite France — photo 1","alt":"Petite France — gallery image 1"},{"id":10,"type":"photo","src":"/images/tours/petite-france/petite-france-couple-colorful.webp","location":"Petite France","caption":"Petite France — photo 2","alt":"Petite France — gallery image 2"},{"id":11,"type":"photo","src":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","location":"Petite France","caption":"Petite France — photo 3","alt":"Petite France — gallery image 3"}],"itineraryStops":[{"number":1,"time":"07:30 / 08:00","duration":"30 min window","name":"Pickup (Hongik University Station or Myeongdong Station)","category":"Coach pickup","description":"Pickup is at one of two Seoul meeting points: **(1) Starbucks Hongik University Station Exit 8 (Mapo-gu)** at 07:30 — the Starbucks storefront sits immediately at the top of Exit 8; OR **(2) Myeongdong Station Exit 2 (Jung-gu)** at 08:00 — the NorthFace flagship store is the visible landmark next to the exit.\n\nBoth pickup points share the same air-conditioned coach, and Hongik passengers board first. Please be at your chosen point **5 minutes before the scheduled time**. This is a noticeably gentler start than the Seoraksan day trips, which leave at 06:00 — Gapyeong is close enough to Seoul that the coach can leave after the first subway trains have been running for two hours.\n\nThe guide distributes a printed Korean-English itinerary card at boarding and confirms the day''s running order, the restroom stop, and the expected return times. From Myeongdong the coach heads northeast on the Seoul-Chuncheon Expressway for the roughly 1.5-hour drive to Gapyeong Wharf.","image":null,"highlights":[],"timeUsed":["Arrive at your chosen pickup point 5 minutes before the scheduled time (~5 min)","Identify the AtoC Korea coach at the marked Starbucks / NorthFace frontage (~5 min)","Board in the pickup queue (~10 min)","Printed Korean-English itinerary card distributed at boarding"],"whyOnRoute":"Two pickup points cover Seoul''s two main visitor clusters: the Hongik University area in Mapo-gu, which suits younger and short-stay travellers, and Myeongdong in Jung-gu, the legacy tourist district around the Lotte, Shilla and Westin hotels. Hongik first and Myeongdong second is the natural order for a northeast-bound run onto the Seoul-Chuncheon Expressway. The 07:30 start is late enough to be comfortable and early enough to put the coach on the Nami ferry at around 10:00, ahead of the independent day-trippers arriving by ITX train.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"Nami Island (Namiseom)","time":"≈ 10:00","number":2,"category":"Ferry-Access Island & K-Drama Landmark","duration":"120 min (2 hours)","timeUsed":["Ferry crossing from Gapyeong Wharf (5-10 minutes including queue)","Free walking time along the Metasequoia / Ginkgo / Korean Pine avenues — half-island circuit ~3 km","Optional bicycle rental (single 7,000 / tandem 14,000 KRW per hour) or electric blue train (3,000 KRW one-way to UNICEF Hall)","Quick on-island snack pause (Sonata Cafe, hotteok, sweet potato latte)","Return ferry to the mainland"],"_poi_meta":{"poi_key":"nami_island","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Korea Tourism Organization (VisitKorea — Nami Island official listing + visa fee schedule)","Naminara Republic Official Site (namisum-en.imweb.me — own corpus on cultural-independence brand)","UNICEF Korea (Nami Island 2010 Child Friendly Park designation + International Children''s Book Festival)","KBS / Korea Times (Winter Sonata 2002 production retrospectives + Japanese tourism boom coverage)","Wikipedia (Namiseom — open corpus on General Nami history + Cheongpyeong Dam 1944 origin)"]},"highlights":["Half-moon river island, ~460,000 m² / 5 km circumference; named after General Nami (1441-1468)","Iconic Metasequoia tree-lined avenue — Winter Sonata (2002) signature filming location","Self-declared ''Naminara Republic'' since 2006 — own flag, currency, passport (tourism concept)","5-min ferry from Gapyeong Wharf (08:00-21:00, every 10-20 min during peak)","On-island wildlife: peacocks (incl. rare albino), ostriches, wild rabbits, squirrels","**Land formed in 1944** when the Japanese-built Cheongpyeong Dam raised the Bukhan River","**UNICEF Child Friendly Park designation 2010** + Nami Island Arts & Education hosts **600+ performances/exhibitions/festivals annually**"],"smartNotes":{"photo":"Metasequoia avenue is the world-famous Winter Sonata shot — best in autumn (golden, late October-early November) or winter (snow). Riverside Lover''s Ginkgo Tree Lane on the south side is quieter and equally photogenic. Albino peacock occasionally appears near Lover''s Lane.","facilities":"On-island restaurants serve Korean comfort food (hotteok, sweet potato latte, tteok-galbi). Sonata Cafe in a traditional hanok is the signature stop. Foreign-card-friendly ticket counter at Gapyeong Wharf — ticket machines do not accept foreign cards, ask at the counter.","tip":"Best seasons: spring (April-May cherry blossoms), autumn (October golden ginkgo + red maple), winter (December-February snow-quiet paths reminiscent of Winter Sonata). Avoid the Sunday late-afternoon ferry queue."},"whyOnRoute":"Nami opens the day because it is the one stop that rewards early light and punishes crowds. The half-moon island''s metasequoia and ginkgo avenues are its signature, and they photograph best before midday when the independent travellers arriving by ITX train and the Gapyeong city tour bus fill the central lanes. Putting it first also means the ferry crossing happens in the morning calm rather than the afternoon wind, and it sets up the rest of the day to run inland and then home without doubling back.","convenience":{"restroom":"Multiple on island and at Gapyeong Wharf","parking":"Gapyeong Wharf 6,000 KRW small car / 10,000 KRW large vehicle"},"description":"Nami Island opens the day''s second chapter with a 5-minute ferry crossing from Gapyeong Wharf onto a half-moon-shaped river island in the Bukhan River. Approximately **460,000 m² (140,000 pyeong) and ~5 km in circumference**, Namiseom is named after **General Nami (Nam Yi, 1441-1468)**, a Joseon-era military commander executed at age 28 after being falsely accused of treason during the reign of King Yejong. \n\nThe island originally became land only during floods; **in 1944 the Japanese colonial government built the Cheongpyeong Dam, raising the river level and making Nami a permanent island**. It found global fame **in 2002 as the filming location for KBS drama ''Winter Sonata''** starring Bae Yong-joon and Choi Ji-woo — the catalyst for the early 2000s Hallyu wave — and continues to draw about **3.3 million visitors annually (1.3 million foreign)**, making it Korea''s most-visited single tourist destination after Seoul, Busan, and Jeju. \n\nSince **March 1, 2006** the island has branded itself as the self-declared **''Naminara Republic''** with its own flag, currency (Nami Tongbo coins), passport, and postal service — a tourism marketing concept rather than an actual political entity. \n\nThe signature **Metasequoia tree-lined avenue** (Winter Sonata''s iconic snowy lane), the **Riverside Lover''s Ginkgo Tree Lane** on the south side, the **Korean Pine Road**, and the recycled-glass **Sequoia Bridge** made from soju bottles are all walkable in a relaxed two hours. On-island wildlife includes peacocks (including rare albinos), ostriches, wild rabbits, and squirrels. \n\n**The Naminara Republic VISA Fee (round-trip ferry included) is included in this tour price**.","visitBasics":{"hours":"Ferry runs from 08:00, last boat in at 21:00 and last boat out at 21:05; every 10-20 min between 09:00 and 18:00 and every 30 min outside that, crossing about 5 minutes. Most on-island shops close by 18:00","closed":"Open year-round","admission":"Naminara Republic visa fee, round-trip ferry included: Adult ₩19,000 — INCLUDED in this tour","walking":"Easy — flat tree-lined paths; the half-perimeter walk is ~3 km, the full loop ~5 km. Bicycle and e-buggy rental available on the island for anyone who would rather not walk it."},"image":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","images":["/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp"],"imageCredits":[{"url":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"Nami Island (Namiseom)","caption":"Nami Island (Namiseom) — photo 1","alt":"Nami Island (Namiseom) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"Nami Island (Namiseom)","caption":"Nami Island (Namiseom) — photo 2","alt":"Nami Island (Namiseom) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"Nami Island (Namiseom)","caption":"Nami Island (Namiseom) — photo 3","alt":"Nami Island (Namiseom) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"Nami Island (Namiseom)","caption":"Nami Island (Namiseom) — photo 4","alt":"Nami Island (Namiseom) — gallery image 4"}]},{"number":3,"time":"≈ 12:15","duration":"60 min","name":"Lunch in Gapyeong (own expense)","category":"Lunch break","description":"The coach stops for an hour at a local restaurant in the Gapyeong Wharf area after Nami Island. Lunch is **not included** — you order and pay for what you want, which typically runs ₩10,000-15,000 per person.\n\nThis is dakgalbi country: the Chuncheon-Gapyeong corridor is the home of **dakgalbi**, sweet-spicy chicken stir-fried at the table with cabbage, sweet potato and rice cakes, usually finished by frying rice in the leftover sauce. **Makguksu** (cold buckwheat noodles) is the traditional partner dish. Vegetarian options are limited but bibimbap is normally available; tell the guide on the coach in the morning and they will call ahead.\n\nBring cash or card — most restaurants in the area take both, but small stalls near the wharf are often cash-only.","image":null,"highlights":[],"timeUsed":["Coach parks and the guide walks the group to the restaurant (~5 min)","Order and eat (~45 min)","Pay individually and reassemble at the coach (~10 min)"],"whyOnRoute":"Lunch sits after Nami rather than before it for two reasons. First, it protects the morning: eating first would push the ferry crossing past midday and into the crowds. Second, the Gapyeong Wharf area is where the restaurants actually are — the Garden of Morning Calm is up a valley road with very little around it, and Petite France has only snack stalls on site. An hour here is the last reliable sit-down meal of the day.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"The Garden of Morning Calm","time":"≈ 13:45","number":4,"category":"Themed Botanical Garden","duration":"90 min","timeUsed":["Garden entry and brief orientation by the driver-guide (~5 min)","Free walking time across the 20 themed sub-gardens (~50 min)","Optional Sunken Garden (Korean Peninsula shape) extended photo time (~10 min)","Winter visits: arrival timed for 17:00 illumination start to see daytime garden + lighting festival ignition","Reassemble at coach (~5 min)"],"_poi_meta":{"poi_key":"garden_of_morning_calm","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Garden of Morning Calm Official Site (morningcalm.co.kr — own corpus on founder + 1996 opening + 20 sub-gardens)","Korea Tourism Organization (VisitKorea — Lighting Festival listing + lighting-fest schedule)","Gyeonggi Cultural Foundation (ggc.ggcf.kr — official cultural promotion entry on Sunken Garden + 200,000 LEDs)","Sahmyook University Department of Horticulture (Prof. Han Sang-kyung honorary professor profile + garden origin)","Wikipedia (Garden of Morning Calm — corpus on Tagore-derived name + 5,000 species + 330,000 m² total)"]},"highlights":["Korea''s signature private arboretum — 330,000 m² with ~5,000 plant species","Founded by Han Sang-kyung of Sahmyook University; opened 1996 (conceived 1992)","Winter Lighting Festival December - March with 200,000+ LEDs (Korea''s first natural-environment light festival)","20 themed sub-gardens — Sunken Garden shaped like the Korean peninsula, Moonlight Garden, Bonsai Garden, Garden of Eden","K-drama filming location for Moonlight Drawn by Clouds and others","**Conceived 1992 / land purchased 1994 / opened May 11, 1996**: Founder Prof. Han Sang-kyung and his wife designed and personally cultivated the entire garden, even selling their house during early financial hardship","**Selected by CNN as one of Korea''s Top 50 Tourist Attractions** — the Sunken Garden''s Korean Peninsula shape (10 large/small flower beds expressing yearning for unification) is the CNN-cited landmark feature","**Cheonnyeonhyang (Chinese juniper)** is the official symbol of Morning Calm — the garden''s signature plant species among the 5,000 total catalogued"],"smartNotes":{"photo":"Spring (cherry blossoms April), summer (lush greens), autumn (foliage October-early November), and winter (lighting festival post-sunset) all photograph differently. The light tunnels at dusk during festival period are the iconic shot.","facilities":"Food Garden serves Korean comfort food (soybean-paste stew, vegetable bibimbap, snow cheese tteokbokki). Good Morning Coffee in a hanok roasting house is the signature cafe. Restaurants close at 20:00.","tip":"For the lighting festival (Dec 5 - Mar 15), the 17:00 arrival catches both daytime garden colours and the illumination ignition. Heavy snow February gives the most magical Frozen-movie scene."},"whyOnRoute":"The Garden of Morning Calm is the day''s middle chapter and its quietest one — 90 minutes is enough to walk the main loop past the Sunken Garden''s Korean-peninsula flower beds and still sit down somewhere. It sits inland and uphill from the river, so it has to come after Nami and before the run home; visiting it in the early afternoon also catches the garden at its warmest, which matters from November through March when the valley holds the cold.","convenience":{"restroom":"Multiple, signposted","parking":"Large free coach parking; coin lockers 1,500-2,000 KRW (500-KRW coins only)"},"description":"About 30 minutes south of Nami Island, the Garden of Morning Calm is **Korea''s signature private arboretum** — approximately **330,000 m²** of curated landscape with around **5,000 plant species**. Conceived in **1992** and opened to the public in **1996**, the garden was designed and personally cultivated by **Han Sang-kyung of Sahmyook University**, who at one point sold his house to fund the project; the name draws from Korea''s longstanding nickname ''**Land of the Morning Calm**'' (Joseon). \n\n**Twenty themed sub-gardens** — including the **Sunken Garden shaped like the Korean peninsula**, the Hometown House Garden, the Bonsai Garden, the Moonlight Garden, the Sky Path, and the Garden of Eden — each carry their own visual identity and have served as filming sets for many K-dramas including **Moonlight Drawn by Clouds**. \n\nFrom early December to mid-March every winter, the garden hosts **Korea''s first natural-environment lighting festival** with more than **200,000 environmentally-friendly LED bulbs** covering the grounds, transforming the garden after sunset into a winter wonderland. \n\n**The name ''Garden of Morning Calm''** comes from Indian poet Rabindranath Tagore, who in 1929 referred to Korea as ''the Land of Morning Calm.'' Han Sang-kyung conceived the project in 1992 while serving as exchange professor in the United States, where he was inspired by world-class private gardens. \n\n**Han and his wife designed and personally labored on the garden**, and during periods of financial difficulty they sold their family home and lived in a small dwelling on the garden''s property to continue construction. \n\nThe garden first opened to the public on May 11, 1996, with 10 themed sections; today it has expanded to 20 themed sub-gardens across 330,000 m². **Admission is INCLUDED in this tour price**.","visitBasics":{"hours":"Roughly 08:30 to sunset (commonly 08:30-19:00), last entry 18:00. During the winter Lighting Festival the garden stays open into the evening — hours change each season, and the guide confirms the day''s closing time on the coach","closed":"Open year-round","admission":"Adult ₩11,000 — INCLUDED in this tour","walking":"Moderate — extensive paths over rolling terrain through the themed sub-gardens; the main loop is mostly stroller-accessible"},"image":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","images":["/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp"],"imageCredits":[{"url":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 1","alt":"The Garden of Morning Calm — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 2","alt":"The Garden of Morning Calm — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 3","alt":"The Garden of Morning Calm — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 4","alt":"The Garden of Morning Calm — gallery image 4"}]},{"number":5,"time":"≈ 16:00","duration":"60 min","name":"Petite France","category":"Le Petit Prince Themed Village","description":"The day''s compact final stop, Petite France is a French cultural theme village built into a hillside above Cheongpyeong Lake about 25 minutes from Nami Island. Opened in July 2008 by founder Han Hong-seop, the 16-building village is themed around ''flowers, stars, and the Little Prince'' (Antoine de Saint-Exupéry''s 1943 novel Le Petit Prince) and houses a Saint-Exupéry memorial hall, the Orgel House (a collection of antique music boxes featuring a 200-year-old centerpiece that still plays), a French housing exhibition, a marionette theater, and a gallery of le coq gaulois (Gallic rooster) sculptures and paintings. \n\nDrama fans visit primarily for the K-drama legacy: Petite France was the filming location for Beethoven Virus (2008), Personal Taste (2010), Secret Garden (2010), My Love from the Star (2013-2014), the 2025 hit Bon Appétit Your Majesty (Maison de Marie doubled as Im Yoon-ah''s character''s room), and the popular variety show Running Man. \n\nThe adjacent Pinocchio & Da Vinci Italian Village offers a combo ticket option for visitors with extra time. The site has been selected for the 2026 Korea-France 140th Anniversary Commemorative Program. \n\nThe village serves a dual function: French cultural theme village + the **Goseong Youth Training Center** that accommodates up to 200 visitors in 4-to-10-person rooms for educational stays. \n\nThe site''s most distinctive architectural feature is the **Traditional France Residence Gallery**: an entire 19th-century French farmhouse from middle-region France, dismantled and reassembled on-site using 200+-year-old wood, roof tiles, and bricks — joined entirely without nails using traditional French timber-frame mortise-and-tenon technique. \n\nPetite France is also **Korea''s only Saint-Exupéry Foundation-licensed organization**, meaning every Little Prince motif on-site is officially authorized by the Foundation in France. \n\nThe adjacent Pinocchio & Da Vinci Italian Village (separate ticket or combo at ₩19,500 adult) extends the day''s European-village content by ~45 min if desired.","highlights":["Opened July 2008; 16 French-style buildings built around the ''Little Prince'' theme (Saint-Exupéry, 1943)","K-drama filming credits: Beethoven Virus (2008), Personal Taste (2010), Secret Garden (2010), My Love from the Star (2013-14), Bon Appétit Your Majesty (2025)","Orgel House: 200-year-old music box collection; Marionette theater with daily performances","Adjacent Pinocchio & Da Vinci Italian Village — combo tickets 19,500 KRW adult","Selected for the 2026 Korea-France 140th Anniversary Commemorative Program","**Korea''s only organization with international license agreement with Saint-Exupéry Foundation in France** — every Little Prince motif on-site is officially licensed","**16 buildings include a 19th-century French farmhouse** reassembled from 200+-year-old wood, roof tiles, and bricks imported from middle-region France, jointed without nails (traditional French timber-frame method)","**2025 K-drama ''Bon Appétit, Your Majesty'' filming location**: ''Maison de Marie'' doubles as Yeon Ji-yeong''s (IM YOON-AH) contemporary-Korea apartment — adds to existing K-drama portfolio (Beethoven Virus 2008, Personal Taste 2010, Secret Garden 2010, My Love from the Star 2013, Vincenzo 2021)"],"timeUsed":["Entry and quick orientation","Walk through the colorful streets and 16 building exhibits + photo points (~45 min)","Optional Marionette show or Orgel demonstration if scheduled","Light refreshment at on-site snack stalls or coffee shop","Optional Pinocchio & Da Vinci Italian Village extension visit (~45 min, combo ticket ₩19,500 adult)"],"whyOnRoute":"Petite France closes the day because of where it is, not just what it is: the village sits on the Cheongpyeong lakeshore already pointing at Seoul, so an hour here costs no extra driving. It is also the day''s smallest stop by some distance — sixteen buildings on a hillside, walkable in under an hour — which makes it the right note to end on after two hours on an island and ninety minutes in a garden. Fans of My Love from the Star, Secret Garden and Beethoven Virus will recognise it immediately.","visitBasics":{"hours":"09:00-18:00, last entry 17:00; closing time shifts with the season and on some evenings for scheduled night events","closed":"Open year-round","admission":"Adult ₩12,000 — INCLUDED in this tour. The combined ticket with the adjacent Pinocchio & Da Vinci Italian Village (₩19,500 adult) is NOT included; the hour on this itinerary covers Petite France only","walking":"Easy — a small village on a gentle hillside slope, comfortably walked in under an hour"},"convenience":{"restroom":"On site","parking":"Free parking"},"smartNotes":{"photo":"Pastel-colored timber-framed houses against the green mountain backdrop are the signature shots. The viewing deck at the top of the hill offers the best wide composition. K-drama scene-spotting is a guided activity for fans (Saint-Exupéry building = My Love from the Star pivotal scenes).","facilities":"Snack stalls only — waffles, dumplings, fish-cake soup, coffee. Most visitors eat at adjacent Italian Village or in nearby Cheongpyeong town instead.","tip":"Best paired with Nami Island and/or Garden of Morning Calm via the Gapyeong City Tour Bus for self-guided trips. Late-afternoon arrival lets you see daytime + early-evening illumination. Visitors expecting a large attraction often note the modest scale (1.5-2 hours typical) — manage expectations."},"_poi_meta":{"poi_key":"petite_france","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","note":"POI verified in KB v1.10 (Batch 7) and reused here unchanged.","sources":["Petite France Official Site (en.pfcamp.com — own corpus on founder + 16-building layout + Goseong Youth Training Center)","Korea Tourism Organization (VisitKorea — Petite France listing + 2025 ''Bon Appétit, Your Majesty'' filming-location verification)","Saint-Exupéry Foundation France (international license agreement — Le Petit Prince motif authorization)","Gapyeong County Tourism Office (gapyeong.go.kr — official local-government attractions listing)","Wikipedia (Petite France theme park — corpus on July 2008 opening + Le Petit Prince theme + organizational structure)"]},"image":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","images":["/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","/images/tours/petite-france/petite-france-couple-colorful.webp","/images/tours/petite-france/petite-france-ai-pastel-village.webp"],"imageCredits":[{"url":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","source":"atoc-korea"},{"url":"/images/tours/petite-france/petite-france-couple-colorful.webp","source":"atoc-korea"},{"url":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","location":"Petite France","caption":"Petite France — photo 1","alt":"Petite France — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/petite-france/petite-france-couple-colorful.webp","location":"Petite France","caption":"Petite France — photo 2","alt":"Petite France — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","location":"Petite France","caption":"Petite France — photo 3","alt":"Petite France — gallery image 3"}]},{"number":6,"time":"≈ 18:30","duration":"≈ 1.5 hour drive","name":"Return to Seoul (Myeongdong or Hongik University Station)","category":"Return drop-off","description":"Departure from Petite France is around 16:45 for the ~1.5-hour run back into Seoul on the Seoul-Chuncheon Expressway. Drop-offs are in reverse pickup order: **Myeongdong Station around 18:30**, then **Hongik University Station around 19:00**.\n\nBoth are subway interchanges, so onward connections are straightforward, and the timing leaves the evening open — you will be back well before Seoul''s restaurants get busy. Friday evenings and Sunday returns can add 20-40 minutes of traffic on the approach to the city; the guide will give the coach''s live estimate on the way in.","image":null,"highlights":[],"timeUsed":["Depart Petite France (~16:45)","Motorway drive with one short comfort stop if needed (~1.5 hours)","Myeongdong Station drop-off (~18:30)","Hongik University Station drop-off (~19:00)"],"whyOnRoute":"Ending at Petite France rather than the Garden of Morning Calm is what makes the return short: the village is already on the Seoul side of Gapyeong, so the coach is pointed home the moment it leaves. Reversing the drop-off order means Myeongdong guests, who boarded last, get out first.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}],"routeFlowStops":[{"name":"Pickup (Hongik / Myeongdong)","type":"origin","theme":"Seoul pickup"},{"name":"Nami Island","type":"primary","theme":"K-drama island"},{"name":"Lunch in Gapyeong","type":"secondary","theme":"Lunch break"},{"name":"The Garden of Morning Calm","type":"primary","theme":"Themed garden"},{"name":"Petite France","type":"primary","theme":"French village"},{"name":"Return to Seoul","type":"return","theme":"Drop-off"}],"routePhases":[{"phase":"Seoul → Gapyeong","duration":"≈ 1.5 hours","description":"Pickup at 07:30 Hongik / 08:00 Myeongdong, then a ~1.5-hour drive northeast to Gapyeong Wharf and the five-minute ferry across to Nami Island."},{"phase":"Nami Island","duration":"≈ 2 hours","description":"Flat tree-lined avenues, the Winter Sonata metasequoia lane, riverside benches and free-roaming ostriches and peacocks. Round-trip ferry and the Naminara Republic visa fee are included."},{"phase":"Lunch → Garden of Morning Calm","duration":"≈ 2.5 hours","description":"Lunch at a local restaurant in Gapyeong (own expense — dakgalbi country), then ~35 minutes inland and uphill to the Garden of Morning Calm for 90 minutes across its themed sub-gardens."},{"phase":"Petite France → Seoul","duration":"≈ 2.5 hours","description":"About forty-five minutes back down to the Cheongpyeong lakeshore for an hour at Petite France, then the ~1.5-hour run into Seoul — Myeongdong around 18:30, Hongik around 19:00."}],"routeShapeIntro":{"title":"How this Seoul day moves","subtitle":"A 07:30 Hongik / 08:00 Myeongdong pickup and a ~1.5-hour drive northeast puts you on the Nami Island ferry before the day-trip crowds thicken. Lunch in Gapyeong town, then the loop turns inland and climbs to the Garden of Morning Calm, and finally drops back down to Petite France on the Cheongpyeong lakeshore — which sits on the way home, so the last stop costs you no backtracking. Back in Seoul around 18:30-19:00."},"whyTourWorks":{"bestFor":["First-time visitors who want Korea''s countryside without a mountain hike","Couples and Hallyu fans here for the Winter Sonata metasequoia avenue","Families and older travellers — every stop is flat or gently rolling","Anyone who wants a full day out of Seoul that still ends before dinner"],"lessIdealFor":["Hikers — there is no mountain and no summit on this route","Travellers who want a single slow stop rather than three","Guests hoping for nightlife or evening city time before 19:00"],"routeLogicSections":[{"title":"Pacing & geography","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Nami first, before the crowds","detail":"Gapyeong is only ~75 km from Seoul, so a 07:30 start reaches the wharf around 10:00 — ahead of the independent travellers arriving on the late-morning ITX trains, and with the low morning light still on the metasequoia avenue."},{"label":"The gardens sit inland, the village sits on the way home","detail":"The Garden of Morning Calm is up in Sang-myeon, ~35 minutes inland from the river; Petite France is back down on the Cheongpyeong lakeshore, already pointed at Seoul. Visiting them in that order means the last stop costs no backtracking."},{"label":"Three admissions, one price","detail":"Nami''s ₩19,000 visa fee (round-trip ferry included), the Garden of Morning Calm''s ₩11,000 and Petite France''s ₩12,000 are all covered — about ₩42,000 of gate fees you don''t queue for or pay again."},{"label":"A shorter day than the Seoraksan routes","detail":"Because nothing here is in Gangwon, the coach spends about three hours on the road instead of five. That is the whole reason this day feels relaxed where the Seoraksan itineraries feel long."}]}]},"practicalAccordionItems":[{"id":"pickup","title":"Pickup & drop-off","preview":"Two Seoul pickup points: **Starbucks Hongik University Station Exit 8 at 07:30** (Mapo-gu), and **Myeongdong Station Exit 2, by the NorthFace flagship, at 08:00** (Jung-gu).","content":["Two Seoul pickup points: **Starbucks Hongik University Station Exit 8 at 07:30** (Mapo-gu), and **Myeongdong Station Exit 2, by the NorthFace flagship, at 08:00** (Jung-gu).","Both pickups share the same coach; please be at your chosen point 5 minutes early.","Return drop-offs in reverse order: **Myeongdong ≈18:30**, **Hongik University ≈19:00**.","Your effective tour length depends on the pickup point: ≈11.5 hours from Hongik, ≈10.5 hours from Myeongdong."]},{"id":"what-to-bring","title":"What to wear & bring","preview":"Comfortable walking shoes — no hiking footwear needed, but you will be on your feet for 5-6 km across the day.","content":["Comfortable walking shoes — no hiking footwear needed, but you will be on your feet for 5-6 km across the day.","Warm layers from November through March; the Gapyeong valleys run several degrees colder than central Seoul and the Nami ferry deck is exposed.","Camera or smartphone — the metasequoia avenue on Nami and the Sunken Garden viewpoint at Morning Calm are the two shots people come for.","Cash and card for lunch (₩10,000-15,000) and any optional extras.","Sun protection in summer; the garden loop has long stretches with little shade."]},{"id":"weather-policy","title":"Weather policy","preview":"Year-round operation.","content":["Year-round operation.","Light rain: the tour runs as scheduled. All three stops hold up in rain — Nami''s tree avenues and the Garden of Morning Calm are both genuinely good in wet weather, and Petite France has indoor exhibition rooms.","Heavy rain or storm: the Nami ferry can be suspended in severe weather. If that happens the guide extends the garden and Petite France stops and the Nami admission is refunded.","Snow: Gapyeong gets more snow than central Seoul. The coach carries winter tyres in season; heavy snowfall can add an hour to the return.","The itinerary order or timings may shift on the day for traffic, weather or venue operating hours — the guide confirms the day''s plan on the coach."]},{"id":"inclusions","title":"What''s included","preview":"Two Seoul pickup points and the same two drop-off points, air-conditioned coach, licensed English-speaking guide.","content":["Two Seoul pickup points and the same two drop-off points, air-conditioned coach, licensed English-speaking guide.","**Nami Island round-trip ferry + Naminara Republic visa fee (₩19,000) — INCLUDED.**","**The Garden of Morning Calm admission (₩11,000) — INCLUDED.**","**Petite France admission (₩12,000) — INCLUDED.**","Tolls and parking fees — INCLUDED.","**NOT included:** lunch and drinks (₩10,000-15,000, own expense), the combined Petite France + Italian Village ticket (₩19,500), Nami Island bicycle or e-buggy rental, the Skyline Zipwire to Nami, and personal spending.","Chinese-speaking guide available on request — please book at least 3 days ahead."]},{"id":"language","title":"Language","preview":"Primary tour language: English.","content":["Primary tour language: English.","Chinese-speaking guide available on request — book 3+ days ahead.","Korean spoken throughout the day for menus, signage, and stall interactions; the guide handles translation."]},{"id":"walking","title":"Walking & terrain","preview":"Easy to moderate — this route has no hiking and no stairs-heavy sections.","content":["Easy to moderate — this route has no hiking and no stairs-heavy sections.","Nami Island: flat, paved, tree-lined avenues; ~3 km over 2 hours is the typical pace. Bicycles and e-buggies can be rented on the island at your own expense.","The Garden of Morning Calm: rolling terrain on mostly paved garden paths; the main loop is broadly stroller-accessible, though some themed sub-gardens sit up short slopes.","Petite France: a small hillside village, gentle slopes, under an hour at a relaxed pace.","Total walking across the day is roughly 5-6 km, spread over three stops with the coach in between. Comfortable shoes are enough — no hiking footwear needed."]},{"id":"lunch","title":"Lunch (own expense)","preview":"Lunch is taken around 12:15 at a local restaurant in the Gapyeong Wharf area, after Nami Island.","content":["Lunch is taken around 12:15 at a local restaurant in the Gapyeong Wharf area, after Nami Island.","This is dakgalbi country — sweet-spicy chicken stir-fried at the table, usually finished by frying rice in the sauce. Makguksu (cold buckwheat noodles) is the classic partner dish.","Budget roughly ₩10,000-15,000 per person. Cash and card are both normally accepted; stalls near the wharf are often cash-only.","Vegetarian options are limited in this region — tell the guide in the morning and they will call ahead."]},{"id":"cancellation","title":"Cancellation","preview":"Free cancellation up to 24 hours before pickup.","content":["Free cancellation up to 24 hours before pickup.","Inside 24 hours: 50% refund.","No-show or missed pickup: no refund — but contact AtoC Korea operations within 10 minutes of pickup time and the coach may briefly wait if running ahead of schedule."]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"See seasonal notes"},"tomorrow":{"temp":"—","label":"See seasonal notes"},"_seasonalSummary":"Seoul + Gangwon: temperate four-season climate. Seoraksan is 5-7°C cooler than Seoul year-round. Hot humid summers (Jun-Aug), crisp cold winters (Dec-Feb), with prime seasons in spring (April cherry blossoms) and autumn (October-November foliage)."},"seasonalVariations":[{"season":"Spring (Mar-May)","description":"Cherry blossom along the Bukhan River in early April, then the Garden of Morning Calm''s spring festival with tens of thousands of tulips. Petite France''s pastel buildings look their best against new green."},{"season":"Summer (Jun-Aug)","description":"Nami''s tree avenues give genuine shade and the island is noticeably cooler than Seoul. The garden is lush but hot and largely unshaded — carry water and sun cover. Expect afternoon showers in the July monsoon."},{"season":"Autumn (Sep-Nov)","description":"The strongest season on this route. Nami''s metasequoia and ginkgo avenues turn through late October into mid-November, and the Garden of Morning Calm runs its autumn chrysanthemum display. Book early — this is peak demand."},{"season":"Winter (Dec-Feb)","description":"The Garden of Morning Calm''s Lighting Festival illuminates the grounds from early December to around mid-March, and the garden stays open into the evening during it. Nami under snow is the Winter Sonata image itself. Dress properly — the valleys are cold and the ferry deck is exposed."}],"bookingTrustItems":[{"icon":"check-circle","title":"All admissions included","description":"Nami ferry + Morning Calm bundled","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600","body":"Nami Island ferry (₩19,000) and Garden of Morning Calm (₩11,000) admissions are pre-paid into the tour price — no per-stop ticket queues. Seoraksan entrance is FREE (abolished May 2023). Total admission savings: ~₩30,000."},{"icon":"users","title":"Licensed English-speaking guide","description":"Korea-licensed tour guide","iconBg":"bg-pink-50/80","iconColor":"text-pink-600","body":"Korea Tourism Organization-licensed guide with English fluency; Chinese-speaking guide available on advance request. Guide narration covers Seoraksan''s Silla-era temple history, Nami''s Winter Sonata legacy, and Morning Calm''s founder story."},{"icon":"shield","title":"Transparent pricing","description":"No hidden shopping stops","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","body":"No ginseng shops, no duty-free, no commissioned souvenir detours. Every minute of the 13-hour day is at an attraction or in transit — what you book is what you experience."}],"bookingSupportSteps":[{"timing":"Immediately","title":"Instant Confirmation","detail":"Booking confirmation with pickup point selection","description":"Instant booking confirmation with Hongik/Myeongdong pickup point selection."},{"timing":"Day before","title":"Pickup Details","detail":"Exact pickup location and vehicle info via WhatsApp/SMS","description":"Weather check, coach plate number, and any seasonal route notes (Morning Calm Lighting Festival timing, Seoraksan foliage peak, etc.) sent the day before."},{"timing":"Morning of","title":"Pickup Confirmation","detail":"Guide identification at pickup point 10 min before departure","description":"Guide waits at Starbucks Hongik Exit 8 from 05:50; at Myeongdong Exit 2 (NorthFace) from 06:20. Photo of the guide and coach sent to your WhatsApp the night before."},{"timing":"During tour","title":"On-tour Support","detail":"Guide narration at each stop + 24/7 ops support","description":"Guide provides on-site narration on Seoraksan''s 652 CE Silla-era founding, Nami''s 1944 Cheongpyeong Dam origin + 2002 Winter Sonata legacy, and Morning Calm''s 1992 conception + 1996 opening."},{"timing":"End of day","title":"Two Drop-off Points","detail":"Myeongdong ~19:00 / Hongik ~19:30","description":"Coach drops at both pickup points in reverse order on return."},{"timing":"After tour","title":"Review & Follow-up","detail":"Optional post-tour review","description":"Post-tour feedback request sent; restaurant or attraction recommendations for the rest of your Seoul stay answered same day."}],"staticQuestions":[{"question":"Are all the admission fees really included?","answer":"Yes — the three gate fees on this route are all covered: Nami Island''s ₩19,000 Naminara Republic visa fee (which includes the round-trip ferry), the Garden of Morning Calm''s ₩11,000, and Petite France''s ₩12,000. That is roughly ₩42,000 per adult you neither queue for nor pay again. Lunch is the main thing you pay for yourself."},{"question":"Is this the same as the Seoraksan tour that also visits Nami and Morning Calm?","answer":"No, and the difference is about three hours of driving. The Seoraksan day trip adds a national park in Gangwon-do, which means a 06:00 start, five hours on the road and a 13-hour day. This tour stays in Gapyeong: a 07:30 start, about three hours of driving, and Petite France in place of the mountain. Choose this one if you want the gardens and the island without the coach time."},{"question":"How much walking is there?","answer":"Roughly 5-6 km across the whole day, broken into three separate stops with the coach in between. There is no hiking, no summit and no long stair climbs. Nami is completely flat, the Garden of Morning Calm rolls gently, and Petite France is a small hillside village. Comfortable everyday shoes are enough."},{"question":"Is it suitable for young children or older travellers?","answer":"Yes, more so than most day trips from Seoul. Every stop is flat or gently sloping, the longest single drive is about 1.5 hours, and the day ends by 19:00. Nami rents bicycles and e-buggies if walking the island is too much, and the Garden of Morning Calm''s main loop is broadly stroller-accessible. The one caveat is total day length — it is still 11 hours door to door."},{"question":"What is the Naminara Republic visa fee?","answer":"It is Nami Island''s admission ticket, styled as a visa because the island declared itself the ''Naminara Republic'' in 2006 as a cultural-tourism concept, complete with its own flag, stamps and immigration desk. Practically it is a ₩19,000 adult ticket that includes the five-minute ferry crossing both ways, and it is included in this tour."},{"question":"Can we visit the Italian Village next to Petite France?","answer":"Not within this itinerary. The Pinocchio & Da Vinci Italian Village sits on the hill directly behind Petite France and needs a combined ticket (₩19,500 adult) plus at least another hour. This tour includes Petite France only and allows an hour there. If the Italian Village matters to you, our private Gapyeong tour can build it in."},{"question":"What happens if it rains?","answer":"The tour runs. All three stops work in light rain — Nami''s tree-lined avenues and the garden are both genuinely atmospheric wet, and Petite France has indoor exhibition rooms including the Saint-Exupéry hall and the Orgel House. The only real weather risk is a storm suspending the Nami ferry, in which case the guide extends the other two stops and the Nami admission is refunded."},{"question":"Is the Garden of Morning Calm Lighting Festival included?","answer":"The festival is not a separate ticket — it runs inside the garden, and your included admission covers it. But this is a daytime itinerary: we are at the garden in the early afternoon, so in the December-to-March festival season you will see the installations unlit rather than illuminated. If the lit garden is your priority, tell us and we will point you at an evening option instead."},{"question":"Which K-dramas were filmed at these stops?","answer":"Nami Island is the Winter Sonata (2002) location — the metasequoia avenue is the scene people come to stand in. Petite France''s credits include Beethoven Virus (2008), Personal Taste (2010), Secret Garden (2010) and My Love from the Star (2013-14). The Garden of Morning Calm has also been used as a filming location, including for Moonlight Drawn by Clouds."},{"question":"What time do we get back to Seoul?","answer":"Myeongdong Station around 18:30 and Hongik University Station around 19:00. Both are subway interchanges. Friday evenings and Sunday returns can add 20-40 minutes on the approach into the city — the guide gives a live estimate on the way in. The timing is deliberately early enough to leave your evening free."},{"question":"Is lunch included?","answer":"No. The coach stops for an hour at a restaurant in the Gapyeong Wharf area and you order and pay for what you want, typically ₩10,000-15,000. This is the home region of dakgalbi — sweet-spicy chicken stir-fried at the table — usually eaten with makguksu noodles. Vegetarian choices are limited, so tell the guide in the morning and they will call ahead."},{"question":"Is there a guide, and in what language?","answer":"Yes — a licensed English-speaking guide travels with the coach for the whole day. A Chinese-speaking guide is available on request if you book at least three days ahead. The stops themselves are largely self-paced: the guide handles admission, timing, orientation and translation rather than delivering a continuous commentary."}],"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]},"sticky_booking_bar":{"note":"Select your date and group size to check live availability and complete your booking.","price":{"amountLabel":"59","currency":"USD","per":"person","salePriceUsd":59}},"pickup_dropoff":{"primary":{"name":"Starbucks Hongik University Station Exit 8","address":"Yanghwa-ro, Mapo-gu, Seoul (in front of the Starbucks at Hongik University Station Exit 8)","time":"07:30 pickup / 19:00 drop-off","instructions":"Meet the guide at the Starbucks storefront immediately above Hongik University Station Exit 8. Look for the AtoC Korea sign and the coach in the pickup queue."},"alternates":[{"name":"Myeongdong Station Exit 2 (NorthFace flagship)","address":"Toegye-ro, Jung-gu, Seoul (NorthFace flagship store at Myeongdong Station Exit 2)","time":"08:00 pickup / 18:30 drop-off","instructions":"Meet the guide in front of the NorthFace flagship store at the top of Myeongdong Station Exit 2."}]},"matching_profile":{"profile_version":1,"is_active":true,"product_id":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","product_type":"bus","route_type":"fixed_route","destination_region":"seoul_gangwon","region_type":"gangwon_seoraksan","vehicle_type":"large_coach","duration_hours":11,"region_tags":["seoul_mapo","seoul_jung","gangwon_sokcho","gyeonggi_gapyeong"],"theme_tags":["national_park","mountain","buddhist_temple","k_drama_filming","themed_garden","hallyu_landmark"],"poi_tags":["nami_island","garden_of_morning_calm","petite_france"],"pace_level":0.7,"walking_level":2,"scenic_level":1,"photo_level":5,"culture_level":0.85,"relax_level":0.5,"first_time_fit":1,"family_fit":0.7,"senior_fit":0.8,"couple_fit":1,"solo_traveler_fit":0.9,"active_traveler_fit":0.85,"adult_family_fit":0.95,"family_with_teens_fit":0.95,"young_kids_fit":0.8,"senior_active_fit":0.75,"senior_general_fit":0.55,"mobility_friendly_fit":0.4,"stroller_fit":0.6,"one_day_fit":1,"same_day_flight_fit":0.1,"rain_fit":0.5,"value_for_money_fit":1,"iconic_landmark_fit":1,"cafe_fit":0.5,"food_fit":0.5,"nature_fit":1,"beach_fit":0.1,"nightlife_fit":0.1,"shopping_fit":0.25,"no_shopping_fit":1,"local_culture_fit":0.7,"storytelling_fit":0.9,"unesco_fit":0,"intangible_heritage_fit":0.5,"indoor_ratio":0.1,"weather_sensitivity":0.65,"comfort_level":0.55,"budget_fit":1,"premium_fit":0.2,"small_group_fit":0.15,"private_fit":0.05,"bus_fit":1,"price_band":"budget","pickup_base":"seoul_central","return_time_band":"19:00-19:30","duration_band":"13h","min_recommended_age":8,"hard_constraints":{"avoidIf":["mobility_limited","wheelchair_required"],"notIdealFor":["very_low_mobility","young_kids_under_6"]},"walking_notes":["13-hour day with ~4-5 km total walking.","Seoraksan paths rocky in places; Nami and Morning Calm flat.","Closed-toe shoes recommended.","Cable car at Seoraksan optional and not included."],"keywords":["seoul seoraksan day tour","nami island day trip","garden of morning calm tour","seoul winter wonder tour","seoraksan nami one day"],"synonym_hints":["seoul to seoraksan day tour","korea three signature stops day trip","seoul winter sonata tour"],"seasonality":"year_round","pickup_base_normalized":"seoul","vehicle_type_legacy":"bus_coach","anchor_poi_keys":["nami_island","garden_of_morning_calm","petite_france"],"private_tour_fit":0.05,"customizable_route_fit":0.05,"flexibility_fit":0.2,"fixed_itinerary_fit":1,"national_park_fit":0,"buddhist_temple_fit":0,"k_drama_filming_fit":1,"winter_sonata_fit":1,"themed_garden_fit":1,"history_culture_fit":0.65,"religious_history_fit":0.45,"premium_dining_fit":0.15,"seasonal_fit":1,"winter_lighting_festival_fit":1,"autumn_foliage_fit":1,"china_mainland_market_fit":0.85,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":1,"se_asia_market_fit":1,"us_market_fit":0.95,"europe_market_fit":0.95,"australia_market_fit":0.95,"japan_market_fit":1,"first_time_korea_fit":1,"seoul_day_trip_fit":1,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true},"matching_metadata":{"primary_themes":["gapyeong","seoul_day_trip","k_drama_filming","themed_garden","river_island","french_village"],"secondary_themes":["winter_sonata","metasequoia_lane","lighting_festival","photo_spots","autumn_foliage","first_time_korea"],"best_for":["first_time_korea","couples","photo_lovers","families","k_drama_fans","seniors"],"not_recommended_for":["hikers_seeking_mountains","nightlife_focused_travelers","travelers_wanting_a_short_half_day"],"anchor_pois":["Nami Island","The Garden of Morning Calm","Petite France"],"anchor_poi_keys":["nami_island","garden_of_morning_calm","petite_france"],"competing_products":["seoul-seoraksan-nami-island-morning-calm-day-tour","seoul-private-nami-morning-calm-petite-france","pocheon-sanjeong-lake-herb-island-art-valley"],"reviews_attribution":"New product (2026-08) — no imported reviews; rating starts at 0.","unesco_fit_note":"No UNESCO property on this route. Cultural weight is popular-culture and horticultural: Winter Sonata''s metasequoia lane on Nami Island, a 330,000 m² private arboretum, and a licensed Le Petit Prince village."},"itinerary_variants":[],"_publication":{"schema_version":"v4_canonical","created":"2026-08-04","last_modified":"2026-08-04","version_history":["v1_authored_2026_08_04"],"fix_passes":{"v1_authored_2026_08_04":"New product (owner instruction 2026-08-04). The Gapyeong trio as a join-in-group coach day tour — the join-in counterpart to the existing private seoul-private-nami-morning-calm-petite-france. Donor A (seoul-seoraksan-nami-island-morning-calm-day-tour) supplied the KB-verified Nami Island and Garden of Morning Calm stop bodies plus Seoul-region weather/trust/support blocks and the two-point Seoul pickup; donor B (seoul-private-nami-morning-calm-petite-france) supplied the Petite France stop body. Pickup, lunch, return and all product-level copy authored fresh in 6 locales (scripts/seoul-gapyeong-content/) with de/fr/it/ru staged. Stop admission/hours re-verified 2026-08-04 against operator and KTO sources. matching_profile derived from donor A with the mountain axes zeroed and garden/K-drama axes raised — full KB calibration pending."}},"page_sections":[]}'::jsonb
)
