  '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","locale":"ja","product_id":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","seo":{"pageTitle":"ソウル発 加平日帰りツアー — 南怡島・晨静苑・プチフランス | AtoC Korea","metaDescription":"ソウル発 加平（カピョン）行き混載バス日帰りツアー。南怡島のメタセコイア並木、晨静苑、プチフランスを巡ります。3か所の入場料すべて込み。弘大入口駅または明洞駅から乗車し、19:00までにソウルへ帰着します。","title":"ソウル発 加平日帰りツアー — 南怡島・晨静苑・プチフランス","description":"ソウル発11.5時間のバス日帰りツアーで加平の3大スポットへ。南怡島のフェリー、晨静苑、プチフランスの入場料はすべて含まれています。","primaryKeywords":["ソウル発 加平 日帰りツアー","南怡島 日帰りツアー","晨静苑 行き方","プチフランス 加平","ソウル発 南怡島 プチフランス 1日ツアー"],"ogImage":"https://www.atockorea.com/images/tours/nami-island/nami-metasequoia-sunset-lake.webp"},"catalog_card":{"slug":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","title":"ソウル発 加平（カピョン）日帰りツアー：南怡島（ナミソム）・晨静苑・プチフランス","subtitle":"加平の三大スポットをバス1日で — 山登りなし、入場料3か所込み","region":"ソウル → 京畿道（加平）","duration":"11.5時間","stopsCount":3,"rating":0,"reviewCount":0,"badges":["ソウル発日帰り","加平（カピョン）","混載グループ","韓国ドラマ","庭園"],"tags":["ソウル発日帰り","加平（カピョン）","混載グループ","韓国ドラマ","庭園","ファミリー向け"],"heroImage":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","thumbnail":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","priceLabel":"","shortCardDescription":"ソウルから最も気軽に行ける田園の一日。南怡島のメタセコイア並木、330,000 m²のテーマ樹木園、そして星の王子さまの村 — 3か所の入場料すべて込みで、19:00までにソウルへ戻ります。"},"headlineLine1":"ソウル発 日帰りツアー","headlineLine2":"南怡島・晨静苑・プチフランス","price":{"amountLabel":"59","currency":"USD","per":"person","salePriceUsd":59},"hero":{"imageUrl":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","imagePosition":"center 45%","images":["/images/tours/nami-island/nami-metasequoia-sunset-lake.webp"],"tagline":"ソウルから日帰りで、加平（カピョン）の代表的な3スポットをゆったり巡るバスの一日 — 並木の続く川の島、韓国で最もよく知られた私設庭園、そして公式ライセンスを受けた「星の王子さま」の村","pills":["ソウル発日帰り","庭園＋韓流","入場料すべて込み"],"meta":{"duration":"11.5時間","region":"ソウル → 京畿道（加平）","stops":"3スポット","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"概要"},{"id":"itinerary","label":"旅程"},{"id":"details","label":"詳細"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"口コミ"}],"glanceItems":[{"icon":"clock","label":"所要時間","value":"11.5時間"},{"icon":"camera","label":"フォトジェニック度","value":"非常に高い","level":5},{"icon":"mountain","label":"景観","value":"高い","level":4},{"icon":"footprints","label":"徒歩量","value":"易しい〜普通","level":2},{"icon":"cloud-rain","label":"雨天時の適合度","value":"普通","level":3},{"icon":"users","label":"ファミリー向け度","value":"非常に良い","level":5},{"icon":"gauge","label":"ペース","value":"ゆったり","level":3}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 1","alt":"南怡島（ナミソム） — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 2","alt":"南怡島（ナミソム） — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 3","alt":"南怡島（ナミソム） — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 4","alt":"南怡島（ナミソム） — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","location":"晨靜苑","caption":"晨靜苑 — photo 1","alt":"晨靜苑 — gallery image 1"},{"id":6,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","location":"晨靜苑","caption":"晨靜苑 — photo 2","alt":"晨靜苑 — gallery image 2"},{"id":7,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","location":"晨靜苑","caption":"晨靜苑 — photo 3","alt":"晨靜苑 — gallery image 3"},{"id":8,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","location":"晨靜苑","caption":"晨靜苑 — photo 4","alt":"晨靜苑 — gallery image 4"},{"id":9,"type":"photo","src":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","location":"プチフランス","caption":"プチフランス — photo 1","alt":"プチフランス — gallery image 1"},{"id":10,"type":"photo","src":"/images/tours/petite-france/petite-france-couple-colorful.webp","location":"プチフランス","caption":"プチフランス — photo 2","alt":"プチフランス — gallery image 2"},{"id":11,"type":"photo","src":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","location":"プチフランス","caption":"プチフランス — photo 3","alt":"プチフランス — gallery image 3"}],"itineraryStops":[{"number":1,"time":"07:30 / 08:00","duration":"30分の受付枠","name":"乗車（弘大入口駅または明洞駅）","category":"バス乗車","description":"乗車場所はソウル市内の2か所のいずれかです：**（1）スターバックス 弘大入口駅8番出口店（麻浦区）** 07:30 — スターバックスの店舗は8番出口を上がってすぐの場所にあります。または **（2）明洞駅2番出口（中区）** 08:00 — 出口の隣にあるノースフェイスの旗艦店が目印です。\n\n2か所とも同じ冷房付きバスに乗車し、弘大入口の乗客が先に乗ります。ご希望の乗車場所に**予定時刻の5分前**までにお越しください。06:00発の雪岳山日帰りツアーと比べると、はっきりと穏やかな出発です。加平はソウルに近く、始発の地下鉄が動き出して2時間経ってからバスが出発できます。\n\nガイドは乗車時に韓英併記の行程カードをお渡しし、その日の巡回順、トイレ休憩、帰着予定時刻を確認します。明洞からはソウル-春川高速道路を北東へ進み、加平船着場まで約1.5時間の道のりです。","image":null,"highlights":[],"timeUsed":["ご希望の乗車場所に、予定時刻の5分前までに到着（約5分）","目印のスターバックス／ノースフェイス前で、AtoC Koreaのバスを確認（約5分）","乗車列に並んで乗車（約10分）","乗車時に韓英併記の行程カードを配布"],"whyOnRoute":"2か所の乗車地点は、ソウルの主要な訪問客エリア2つをカバーします。麻浦区の弘大エリアは若い旅行者や短期滞在の方に向き、中区の明洞はロッテ・新羅・ウェスティンといったホテルが集まる昔ながらの観光地区です。北東へ向かってソウル-春川高速道路に乗る行程では、弘大入口が先、明洞が後という順序が自然です。07:30発は無理のない時間でありながら、ITX列車で来る個人の日帰り客より先、10:00ごろに南怡島行きのフェリーに乗れる早さです。","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"南怡島（ナミソム）","time":"≈ 10:00","number":2,"category":"加平郡の河中島 — 「冬のソナタ」ロケ地・ポプラ並木","duration":"120分（2時間）","timeUsed":["加平桟橋からフェリーで渡る（待ち時間含む5〜10分）","メタセコイア／イチョウ／チョウセンゴヨウの並木道を自由散策 — 島の半周コース約3km","オプション：自転車レンタル（シングル7,000ウォン／タンデム14,000ウォン、1時間あたり）または電気式ブルートレイン（ユニセフホールまで片道3,000ウォン）","島内での軽食休憩（ソナタカフェ、ホットク、さつまいもラテ）","本土へ戻るフェリーに乗船"],"_poi_meta":{"poi_key":"nami_island","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Korea Tourism Organization (VisitKorea — Nami Island official listing + visa fee schedule)","Naminara Republic Official Site (namisum-en.imweb.me — own corpus on cultural-independence brand)","UNICEF Korea (Nami Island 2010 Child Friendly Park designation + International Children''s Book Festival)","KBS / Korea Times (Winter Sonata 2002 production retrospectives + Japanese tourism boom coverage)","Wikipedia (Namiseom — open corpus on General Nami history + Cheongpyeong Dam 1944 origin)"]},"highlights":["**「冬のソナタ」（2002年）**のロケ地 — 東アジアKドラマ聖地","**メタセコイア・ポプラ並木** — 秋の黄金色の落葉が絶景","春：菜の花畑。夏：緑のトンネル。秋：紅葉。冬：雪景色 — **4シーズン対応**","加平港からフェリーで5〜10分（**フェリー代金含まれます**）","年間約**200万人**が訪れる東アジアのKドラマ観光地"],"smartNotes":{"photo":"メタセコイア並木 — 秋の黄金色と冬の雪景色が代表的なショット。","facilities":"島内に韓屋風レストラン、カフェ、お土産店。","tip":"ベストシーズン：春（4〜5月桜）、秋（10月黄金のイチョウ）。週末ピーク時は早めの到着を。"},"whyOnRoute":"南怡島を最初に訪れるのは、ここが朝の光に報われ、混雑に損なわれる唯一の立ち寄り先だからです。半月形をしたこの島のメタセコイアとイチョウの並木道は島の看板であり、ITX列車で来る個人旅行者や加平シティツアーバスが中央の道を埋める正午前が、最も写真に向いています。最初に置くことで、フェリーでの渡河も午後の風ではなく朝の静けさの中になります。そしてこのあとは内陸へ向かい、引き返すことなくそのまま帰路につく流れが組み立てられます。","convenience":{"restroom":"島内複数か所＋カピョン桟橋","parking":"カピョン桟橋 小型車₩6,000/大型車₩10,000"},"description":"**南怡島**は京畿道加平郡の北漢江に浮かぶ**半月形の河中島（周囲4.6km）**で、**朝鮮王朝第7代王の庶子・南怡将軍**にちなんで名付けられた。1965年に春川ダム建設で生まれた人工島。日本での「**冬のソナタ****」（2002年、KBS）の爆発的ヒット**以降、東アジアのKドラマツーリズムの聖地として知られ、韓国国内外から年間**約200万人**が訪れる。\n\n最も有名な景観は**メタセコイアのポプラ並木** — 秋の黄金色の落葉が絶景。また、** （ロシアオリーブ）の並木**・**（菜の花）畑**・**（コスモス）畑**など、季節ごとに異なる絵画的な風景が島内各所に広がります。島内を自転車で回ることも可能（レンタル有料）。加平港からフェリーで5〜10分（フェリー代金はツアーに含まれます）。","visitBasics":{"hours":"フェリーは08:00から運航、最終便の入島は21:00、出島は21:05です。09:00〜18:00は10〜20分間隔、それ以外の時間帯は30分間隔で、乗船時間は約5分です。島内の店舗の多くは18:00までに閉まります","closed":"通年営業","admission":"ナミナラ共和国ビザ料金（往復フェリー込み）：大人 ₩19,000 — 本ツアーに含まれます","walking":"易しい — 平坦な並木道です。半周で約3 km、一周で約5 km。歩くのが大変な方のために、島内で自転車と電動カートのレンタルがあります。"},"image":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","images":["/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp"],"imageCredits":[{"url":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 1","alt":"南怡島（ナミソム） — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 2","alt":"南怡島（ナミソム） — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 3","alt":"南怡島（ナミソム） — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 4","alt":"南怡島（ナミソム） — gallery image 4"}]},{"number":3,"time":"≈ 12:15","duration":"60分","name":"加平での昼食（各自負担）","category":"昼食休憩","description":"南怡島のあと、加平船着場周辺の地元レストランで1時間停車します。昼食は**含まれていません** — お好きなものを注文してお支払いいただきます。目安は1人あたり₩10,000〜15,000です。\n\nここはタッカルビの本場です。春川-加平一帯は**タッカルビ**（甘辛く味付けした鶏肉を、キャベツ・さつまいも・トックとともに鉄板で炒める料理。最後に残ったタレでご飯を炒めるのが定番です）の郷土です。**マッククス**（冷たいそば）が伝統的な相棒の一皿です。ベジタリアン向けの選択肢は限られますが、ビビンバはたいてい用意があります。朝、車内でガイドにお伝えいただければ、事前に店へ連絡します。\n\n現金かカードをお持ちください。この地域のレストランはほとんどが両方使えますが、船着場近くの小さな屋台は現金のみのことが多いです。","image":null,"highlights":[],"timeUsed":["バスが駐車し、ガイドがレストランまで案内（約5分）","注文と食事（約45分）","各自で会計を済ませ、バスに集合（約10分）"],"whyOnRoute":"昼食が南怡島の前ではなく後にあるのには、2つの理由があります。第一に、午前中を守るためです。先に食事をとるとフェリーでの渡河が正午を過ぎ、混雑の中に入ってしまいます。第二に、レストランが実際にあるのは加平船着場の周辺だからです。晨静苑は周囲にほとんど何もない谷の道の上にあり、プチフランスの敷地内には軽食の売店しかありません。ここでの1時間が、この日最後の確実な着席の食事になります。","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"晨靜苑","time":"≈ 13:45","number":4,"category":"「朝の静けさ」の庭園 — 10万平米の植物園・加平郡","duration":"90分","timeUsed":["ドライバーガイドによる庭園入場と簡単なオリエンテーション（約5分）","20のテーマ別サブガーデンを自由に散策（約50分）","オプション：サンクンガーデン（朝鮮半島の形）での撮影延長時間（約10分）","冬季訪問：昼間の庭園とライトアップ点灯式の両方をお楽しみいただけるよう、イルミネーション開始時刻の17:00に合わせて到着","コーチ（バス）に集合（約5分）"],"_poi_meta":{"poi_key":"garden_of_morning_calm","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","note":"POI verified in KB v1.10 (Batch 7) and reused here unchanged.","sources":["Garden of Morning Calm Official Site (morningcalm.co.kr — own corpus on founder + 1996 opening + 20 sub-gardens)","Korea Tourism Organization (VisitKorea — Lighting Festival listing + lighting-fest schedule)","Gyeonggi Cultural Foundation (ggc.ggcf.kr — official cultural promotion entry on Sunken Garden + 200,000 LEDs)","Sahmyook University Department of Horticulture (Prof. Han Sang-kyung honorary professor profile + garden origin)","Wikipedia (Garden of Morning Calm — corpus on Tagore-derived name + 5,000 species + 330,000 m² total)"]},"highlights":["韓国を代表する私設樹木園 — 330,000m²に約5,000種の植物","三育大学のハン・サンギョン氏が創設。1996年開園(構想は1992年)","冬期ライティング・フェスティバル 2025年12月5日〜2026年3月15日、30,000個以上のLED(韓国初の自然環境ライト・フェスティバル)","20のテーマ別小庭園 — 韓半島の形をした沈床園、ムーンライト・ガーデン、盆栽園、エデンの園","Glossary ''K-drama filming location'' → 韓国ドラマのロケ地. JA uses ''Kドラマのロケ地'' (loanword K). For consistency with glossary: ''複数の韓国ドラマのロケ地''. Note: corpus uses Kドラマ 26x vs 韓国ドラマ 2x — systemic. May be acceptable native usage; minor.","**1992年構想/1994年土地購入/1996年5月11日開園**:創設者ハン・サンギョン教授(三育大学園芸学科)と妻が全庭を自ら設計・栽培。初期の財政難期には自宅を売却","**CNN「韓国観光地トップ50」選出** — 沈床園の韓半島形(統一を願う10の大小花壇)がCNN指摘の象徴的特徴","**ライティング・フェスティバルでは20万個以上の環境配慮型LED電球**(12〜3月)を使用 — 韓国初の自然環境ライト・フェスティバル。日没17時頃から毎晩点灯","**チョンニョンヒャン(中国産イブキ)**が朝の静けさ樹木園の公式シンボル — 5,000種の中で園を代表する樹種"],"smartNotes":{"photo":"春(4月の桜)、夏(濃緑)、秋(10月〜11月初旬の紅葉)、冬(日没後のライトアップ)それぞれ異なる写真表現が可能。フェスティバル期間中の夕暮れの光のトンネルが象徴的なショット。","facilities":"「フードガーデン」では韓国の家庭料理(味噌チゲ、野菜ビビンバ、雪チーズトッポッキ)を提供。シグニチャーカフェは韓屋焙煎所の「Good Morning Coffee」。レストランは20:00閉店。","tip":"ライティング・フェスティバル(12月5日〜3月15日)は16時頃到着で日中の庭園を見たあと、点灯(17時頃〜)まで滞在を。2月の大雪は『アナと雪の女王』のような幻想的な景色を作ります。"},"whyOnRoute":"晨静苑（モーニングカーム）はこの一日の中盤であり、最も静かな章です。90分あれば、韓半島をかたどった花壇のある沈床園（サンクンガーデン）を通るメインの周回路を歩き、それでもどこかに腰を下ろす余裕があります。川から内陸へ、坂を上った場所にあるため、南怡島のあと、帰路の前に置くほかありません。午後の早い時間に訪れることで、庭園が一日で最も暖かい時間帯に当たります。これは、谷が冷え込む11月から3月にかけて効いてきます。","convenience":{"restroom":"複数、案内表示あり","parking":"大型無料駐車場。コインロッカー1,500〜2,000 KRW(500ウォン硬貨のみ)"},"description":"南怡島から南へ約30分、朝の静けさ樹木園は韓国を代表する私設樹木園で、約330,000m²の整備された景観の中に約5,000種の植物が育まれています。1992年に構想、1996年に一般公開され、三育大学のハン・サンギョン教授が自ら設計・栽培を手がけました(資金不足の時期には自宅を売却して建設を続けた逸話も)。名称は韓国の古来の異名「朝鮮(朝の静けさの国)」に由来。\n\n20のテーマ別小庭園 — 韓半島の形をした「沈床園」、故郷の家ガーデン、盆栽園、ムーンライト・ガーデン、空の道、エデンの園など — それぞれが独自の視覚的アイデンティティを持ち、『雲が描いた月明り』をはじめ多数のKドラマのロケ地となっています。毎年12月初旬から3月中旬まで、韓国初の自然環境ライティング・フェスティバルを開催 — 2025〜2026年版は2025年12月5日〜2026年3月15日で、3万個以上のLEDが園内を覆い、日没後の庭園を冬のワンダーランドに変貌させます。\n\nフェスティバル期間の営業時間は日〜金 11:00〜21:00、土 11:00〜23:00。期間外は08:30〜19:00(最終入場18:00)で運営します。**「朝の静けさ樹木園」**の名は、1929年に韓国を「朝の静けさの国」と呼んだインドの詩人ラビンドラナート・タゴールに由来します。ハン・サンギョン教授は1992年、米国で交換教授を務めていた際に世界一流の私設庭園に触発され、本プロジェクトを構想。\n\n1994年に土地を購入 — もとは焼畑農業で開かれた荒れた石ころ地でした。**ハン氏夫妻が自ら設計・労働を行い**、財政難の時期には自宅を売却して敷地内の小屋に住み込みで建設を続けました。庭園は1996年5月11日に10のテーマセクションで初公開 — 現在は330,000m²に20のテーマ別庭園を擁するまでに拡張されています。","visitBasics":{"hours":"おおむね08:30から日没まで（一般に08:30〜19:00）、最終入園18:00。冬のライティングフェスティバル期間中は夜まで開園します — 開園時間は季節ごとに変わるため、その日の閉園時刻はガイドが車内で確認します","closed":"通年営業","admission":"大人 ₩11,000 — 本ツアーに含まれます","walking":"普通 — テーマ別の庭園を巡る、起伏のある地形に広がる園路です。メインの周回路はおおむねベビーカーで通行できます"},"image":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","images":["/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp"],"imageCredits":[{"url":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","location":"晨靜苑","caption":"晨靜苑 — photo 1","alt":"晨靜苑 — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","location":"晨靜苑","caption":"晨靜苑 — photo 2","alt":"晨靜苑 — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","location":"晨靜苑","caption":"晨靜苑 — photo 3","alt":"晨靜苑 — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","location":"晨靜苑","caption":"晨靜苑 — photo 4","alt":"晨靜苑 — gallery image 4"}]},{"number":5,"time":"≈ 16:00","duration":"60分","name":"プチフランス","category":"星の王子さまテーマビレッジ","description":"その日のコンパクトな最終スポット、プチフランスは、南怡島から約25分、清平湖を見下ろす丘の斜面に建てられたフランス文化テーマビレッジです。2008年7月に創設者ハン・ホンソプにより開村した16棟から成るこのビレッジは、「花・星・星の王子さま」（アントワーヌ・ド・サン＝テグジュペリの1943年の小説『星の王子さま』）をテーマに、サン＝テグジュペリ記念館、オルゴールハウス（現在も演奏可能な200年前の中心作品を含むアンティークオルゴールのコレクション）、フランス住宅展示館、マリオネット劇場、そしてル・コック・ゴーロワ（ガリアの雄鶏）の彫刻・絵画ギャラリーを有しています。\n\nドラマファンが訪れる主な理由は、その韓国ドラマの聖地としての魅力です。プチフランスは『ベートーベン・ウイルス』（2008年）、『個人の趣向』（2010年）、『シークレット・ガーデン』（2010年）、『星から来たあなた』（2013〜2014年）、2025年のヒット作『ご飯は食べましたか、陛下』（メゾン・ド・マリーがイム・ユナの演じるキャラクターの部屋として使用）、そして人気バラエティ番組『ランニングマン』のロケ地となっています。\n\n隣接するピノキオ＆ダ・ヴィンチ・イタリアンビレッジでは、時間に余裕のある方向けにセット券が販売されています。また、当施設は2026年の韓仏修好140周年記念プログラムに選定されています。\n\nこのビレッジはフランス文化テーマビレッジとしての機能に加え、4〜10人部屋で最大200名を収容できる**ゴソン青少年研修センター**としても機能し、教育目的の滞在を提供しています。\n\n最も特徴的な建築的見どころは**伝統的フランス住居ギャラリー**です。フランス中部地方から持ち込まれた19世紀のフランス農家が丸ごと現地で解体・再組立てされており、200年以上前の木材・屋根瓦・レンガを使用し、伝統的なフランス木造軸組工法（ほぞ・ほぞ穴技法）で釘を一切使わずに接合されています。\n\nプチフランスはまた、**韓国で唯一サン＝テグジュペリ財団の公認を受けた施設**でもあり、施設内のすべての星の王子さまのモチーフはフランスの財団により正式にライセンスされています。\n\n隣接するピノキオ＆ダ・ヴィンチ・イタリアンビレッジ（別料金またはセット券₩19,500／大人）では、ご希望の場合、欧州ビレッジ体験をさらに約45分延長することができます。","highlights":["2008年7月開村、フランス風建物16棟が「星の王子さま」テーマ（サン＝テグジュペリ、1943年）で構成","韓国ドラマ撮影実績：ベートーベン・ウイルス（2008年）、個人の趣向（2010年）、シークレット・ガーデン（2010年）、星から来たあなた（2013〜2014年）、ご飯は食べましたか陛下（2025年）","オルゴールハウス：200年前のオルゴールコレクション、マリオネット劇場（毎日公演あり）","隣接するピノキオ＆ダ・ヴィンチ・イタリアンビレッジ — セット券₩19,500（大人）","2026年韓仏修好140周年記念プログラムに選定","**フランスのサン＝テグジュペリ財団と国際ライセンス契約を結ぶ韓国唯一の施設** — 敷地内のすべての星の王子さまのモチーフが正式にライセンス取得済み","**16棟の中には19世紀のフランス農家**が含まれており、フランス中部地方から持ち込まれた200年以上前の木材・屋根瓦・レンガを使い、釘を一切使わずに再組立てされています（伝統的なフランス木造軸組工法）","**2025年韓国ドラマ『ご飯は食べましたか、陛下』のロケ地**：「メゾン・ド・マリー」がヨン・ジヨン（イム・ユナ）の現代韓国のアパートとして登場 — 既存の韓国ドラマ実績（ベートーベン・ウイルス2008年、個人の趣向2010年、シークレット・ガーデン2010年、星から来たあなた2013年、ヴィンチェンツォ2021年）にさらに加わる"],"timeUsed":["入場および簡単な見学","カラフルな街並みと16棟の展示施設を散策＋フォトスポット（約45分）","マリオネットショーまたはオルゴール実演（スケジュールに応じて任意参加）","場内の軽食スタンドまたはカフェで軽食","任意：隣接するピノキオ＆ダ・ヴィンチ・イタリアンビレッジに立ち寄る（約45分、セット券₩19,500 大人）"],"whyOnRoute":"プチフランスが一日の締めくくりになるのは、それが何であるかだけでなく、どこにあるかによります。この村は清平湖畔の、すでにソウルを向いた位置にあるため、ここで1時間過ごしても余分な走行は発生しません。またこの日で群を抜いて小さい立ち寄り先でもあります — 丘の斜面に16棟、1時間かからずに歩けます。島で2時間、庭園で90分過ごしたあとの締めくくりとして、ちょうどよい一幕です。『星から来たあなた』『シークレット・ガーデン』『ベートーベン・ウイルス』のファンなら、すぐに見覚えがあるはずです。","visitBasics":{"hours":"09:00〜18:00、最終入場17:00。閉場時刻は季節によって変わり、夜間イベントが予定されている日にも変わることがあります","closed":"通年営業","admission":"大人 ₩12,000 — 本ツアーに含まれます。隣接するピノキオ＆ダ・ヴィンチ・イタリアンビレッジとのセット券（大人 ₩19,500）は含まれません。この行程の1時間はプチフランスのみです","walking":"易しい — 緩やかな丘の斜面にある小さな村で、1時間かからずに無理なく歩けます"},"convenience":{"restroom":"現地にて","parking":"無料駐車場"},"smartNotes":{"photo":"緑豊かな山々を背景にしたパステルカラーの木骨造りの家々が定番の撮影スポットです。丘の頂上にある展望デッキからは、最も広角な構図が楽しめます。韓国ドラマのロケ地巡りはファン向けのガイド付きアクティビティです（サン＝テグジュペリの建物＝「星から来たあなた」の重要シーンの舞台）。","facilities":"スナックスタンドのみ — ワッフル、餃子、おでん汁、コーヒー。ほとんどの訪問者は、隣接するイタリアン・ビレッジか近くの清平（チョンピョン）の町で食事をとります。","tip":"加平（カピョン）シティツアーバスを利用して、南怡島（ナミソム）や朝の静寂の庭（モーニング・カーム）と組み合わせるのがおすすめです（個人旅行者向け）。午後遅めに到着すると、昼間の景色と夕方のライトアップを両方楽しめます。大型観光地を期待して訪れる方は、こじんまりとした規模（通常1.5〜2時間）を事前にご承知おきください。"},"_poi_meta":{"poi_key":"petite_france","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","note":"POI verified in KB v1.10 (Batch 7) and reused here unchanged.","sources":["Petite France Official Site (en.pfcamp.com — own corpus on founder + 16-building layout + Goseong Youth Training Center)","Korea Tourism Organization (VisitKorea — Petite France listing + 2025 ''Bon Appétit, Your Majesty'' filming-location verification)","Saint-Exupéry Foundation France (international license agreement — Le Petit Prince motif authorization)","Gapyeong County Tourism Office (gapyeong.go.kr — official local-government attractions listing)","Wikipedia (Petite France theme park — corpus on July 2008 opening + Le Petit Prince theme + organizational structure)"]},"image":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","images":["/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","/images/tours/petite-france/petite-france-couple-colorful.webp","/images/tours/petite-france/petite-france-ai-pastel-village.webp"],"imageCredits":[{"url":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","source":"atoc-korea"},{"url":"/images/tours/petite-france/petite-france-couple-colorful.webp","source":"atoc-korea"},{"url":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","location":"プチフランス","caption":"プチフランス — photo 1","alt":"プチフランス — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/petite-france/petite-france-couple-colorful.webp","location":"プチフランス","caption":"プチフランス — photo 2","alt":"プチフランス — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","location":"プチフランス","caption":"プチフランス — photo 3","alt":"プチフランス — gallery image 3"}]},{"number":6,"time":"≈ 18:30","duration":"約1.5時間の走行","name":"ソウルへ帰着（明洞駅または弘大入口駅）","category":"帰着・降車","description":"プチフランス発は16:45ごろ。ソウル-春川高速道路を通って、ソウルまで約1.5時間の道のりです。降車は乗車と逆の順序で、**明洞駅に18:30ごろ**、続いて**弘大入口駅に19:00ごろ**です。\n\nどちらも地下鉄の乗換駅なので、その先の移動もしやすく、夜の時間もそのまま空きます。ソウルのレストランが混み合うずっと前に戻れます。金曜の夕方や日曜の帰路は、市内に近づくあたりで20〜40分ほど余計にかかることがあります。その日の見込みは、ガイドが車内でお伝えします。","image":null,"highlights":[],"timeUsed":["プチフランス発（16:45ごろ）","高速道路を走行、必要に応じて短い休憩1回（約1.5時間）","明洞駅で降車（18:30ごろ）","弘大入口駅で降車（19:00ごろ）"],"whyOnRoute":"晨静苑ではなくプチフランスで終えることが、帰路を短くしています。この村はすでに加平のソウル側にあるため、出発した瞬間からバスは家路を向いています。降車の順序を逆にすることで、最後に乗った明洞の方が最初に降りられます。","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}],"routeFlowStops":[{"name":"乗車（弘大入口／明洞）","type":"origin","theme":"Seoul pickup"},{"name":"南怡島（ナミソム）","type":"primary","theme":"K-drama island"},{"name":"加平で昼食","type":"secondary","theme":"Lunch break"},{"name":"晨静苑","type":"primary","theme":"Themed garden"},{"name":"プチフランス","type":"primary","theme":"French village"},{"name":"ソウルへ帰着","type":"return","theme":"Drop-off"}],"routePhases":[{"phase":"ソウル → 加平（カピョン）","duration":"約1.5時間","description":"07:30に弘大入口駅、08:00に明洞駅で乗車し、北東へ約1.5時間走って加平船着場へ。そこから5分のフェリーで南怡島（ナミソム）へ渡ります。"},{"phase":"南怡島（ナミソム）","duration":"約2時間","description":"平坦な並木道、『冬のソナタ』のメタセコイア並木、川沿いのベンチ、そして放し飼いのダチョウやクジャク。往復フェリーとナミナラ共和国のビザ料金が含まれます。"},{"phase":"昼食 → 晨静苑","duration":"約2.5時間","description":"加平の地元レストランで昼食（各自負担・タッカルビの本場です）。その後、内陸へ約35分上って晨静苑へ。テーマ別の庭園を90分かけて歩きます。"},{"phase":"プチフランス → ソウル","duration":"約2.5時間","description":"45分ほど下って清平湖畔のプチフランスへ、滞在1時間。その後、約1.5時間かけてソウルへ — 明洞は18:30ごろ、弘大入口は19:00ごろです。"}],"routeShapeIntro":{"title":"ソウル発のこの一日はこう動きます","subtitle":"07:30に弘大入口駅、08:00に明洞駅で乗車し、北東へ約1.5時間。日帰り客が増えきる前に南怡島行きのフェリーに乗ります。加平の町で昼食をとったあと、ルートは内陸へ入って晨静苑へ上り、最後は清平（チョンピョン）湖畔まで下ってプチフランスへ。ここはソウルへの帰り道の途中にあるため、最後の立ち寄りで引き返す必要がありません。ソウルには18:30〜19:00ごろ到着します。"},"whyTourWorks":{"bestFor":["山登りなしで韓国の田園風景を見たい、初めて訪れる方","『冬のソナタ』のメタセコイア並木を目当てに来たカップルや韓流ファン","ご家族連れや年配の方 — どの立ち寄り先も平坦か、緩やかな起伏です","ソウルを丸一日離れつつ、夕食前には戻ってきたい方"],"lessIdealFor":["登山をしたい方 — このルートに山も山頂もありません","3か所を回るより、1か所をゆっくり過ごしたい方","19:00より前に夜の街や市内での時間を確保したい方"],"routeLogicSections":[{"title":"ペースと地理","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"混雑の前に、まず南怡島","detail":"加平はソウルから約75 kmしか離れていないため、07:30発なら10:00ごろには船着場に着きます。午前遅くのITX列車で到着する個人旅行者より先に入れますし、メタセコイア並木にはまだ朝の低い光が残っています。"},{"label":"庭園は内陸に、村は帰り道に","detail":"晨静苑は川から内陸へ約35分上った上面（サンミョン）にあり、プチフランスは清平湖畔まで下りた、すでにソウルを向いた位置にあります。この順で回れば、最後の立ち寄りで引き返す必要がありません。"},{"label":"3か所の入場料が、ひとつの料金に","detail":"南怡島の₩19,000のビザ料金（往復フェリー込み）、晨静苑の₩11,000、プチフランスの₩12,000はすべて含まれています。合計およそ₩42,000の入場料を、並ぶことも、その場で払い直すこともなく済ませられます。"},{"label":"雪岳山ルートより短い一日","detail":"江原道まで足を延ばさないため、バスの走行時間は5時間ではなく約3時間です。雪岳山の行程が長く感じられるのに対して、この一日がゆったり感じられる理由は、そこにあります。"}]}]},"practicalAccordionItems":[{"id":"pickup","title":"乗車・降車場所","preview":"ソウル市内の乗車地点2か所：**スターバックス 弘大入口駅8番出口店 07:30**（麻浦区）、**明洞駅2番出口・ノースフェイス旗艦店前 08:00**（中区）。","content":["ソウル市内の乗車地点2か所：**スターバックス 弘大入口駅8番出口店 07:30**（麻浦区）、**明洞駅2番出口・ノースフェイス旗艦店前 08:00**（中区）。","2か所とも同じバスに乗車します。ご希望の場所に5分前までにお越しください。","帰りの降車は逆順で、**明洞 ≈18:30**、**弘大入口 ≈19:00**。","実際のツアー所要時間は乗車場所によって異なります：弘大入口から≈11.5時間、明洞から≈10.5時間。"]},{"id":"what-to-bring","title":"服装と持ち物","preview":"歩きやすい靴 — 登山靴は必要ありませんが、1日で5〜6 kmを歩くことになります。","content":["歩きやすい靴 — 登山靴は必要ありませんが、1日で5〜6 kmを歩くことになります。","11月から3月は暖かい重ね着を。加平の谷はソウル中心部より数度低く、南怡島のフェリーの甲板は吹きさらしです。","カメラかスマートフォン — 南怡島のメタセコイア並木と晨静苑の沈床園の眺めが、皆さんが目当てにする2枚です。","昼食（₩10,000〜15,000）とオプションの支払いのための現金とカード。","夏は日よけ対策を。庭園の周回路には、日陰の少ない区間が長く続きます。"]},{"id":"weather-policy","title":"天候について","preview":"通年運行です。","content":["通年運行です。","小雨：予定どおり運行します。3か所とも雨に耐えます — 南怡島の並木道と晨静苑はどちらも雨の日にこそ良く、プチフランスには屋内の展示室があります。","大雨・荒天：悪天候時は南怡島のフェリーが運休することがあります。その場合、ガイドが樹木園とプチフランスの滞在を延ばし、南怡島の入場料は返金します。","雪：加平はソウル中心部より雪が多く降ります。冬季はバスに冬用タイヤを装着しますが、大雪の際は帰路が1時間ほど延びることがあります。","交通・天候・施設の営業時間により、当日に行程の順序や時間が変わることがあります — その日の計画はガイドが車内で確認します。"]},{"id":"inclusions","title":"含まれるもの","preview":"ソウル市内2か所の乗車地点と同じ2か所の降車地点、冷房付きバス、有資格の英語ガイド。","content":["ソウル市内2か所の乗車地点と同じ2か所の降車地点、冷房付きバス、有資格の英語ガイド。","**南怡島の往復フェリー＋ナミナラ共和国ビザ料金（₩19,000）— 含まれます。**","**晨静苑入場料（₩11,000）— 含まれます。**","**プチフランス入場料（₩12,000）— 含まれます。**","通行料・駐車料金 — 含まれます。","**含まれないもの：** 昼食と飲み物（₩10,000〜15,000、各自負担）、プチフランス＋イタリアンビレッジのセット券（₩19,500）、南怡島の自転車・電動カートのレンタル、南怡島へのスカイライン・ジップワイヤー、その他個人的な出費。","中国語ガイドはご要望に応じて手配できます — 3日前までにご予約ください。"]},{"id":"language","title":"言語","preview":"メインのツアー言語：英語。","content":["メインのツアー言語：英語。","中国語対応ガイドはリクエストにより手配可能 — 3日以上前にご予約ください。","メニュー・看板・屋台でのやり取りには韓国語が使用されますが、ガイドが通訳いたします。"]},{"id":"walking","title":"徒歩と地形","preview":"易しい〜普通 — このルートに登山はなく、階段の多い区間もありません。","content":["易しい〜普通 — このルートに登山はなく、階段の多い区間もありません。","南怡島：平坦で舗装された並木道。2時間で約3 kmが目安のペースです。島内では自転車や電動カートを各自負担でレンタルできます。","晨静苑：起伏のある地形に、おおむね舗装された園路。メインの周回路はおおむねベビーカーで通行できますが、テーマ別の庭園の一部は短い坂の上にあります。","プチフランス：丘にある小さな村で、傾斜は緩やかです。ゆっくり歩いても1時間かかりません。","1日の歩行距離は合計およそ5〜6 kmで、間にバス移動を挟んだ3か所に分かれています。歩きやすい靴で十分で、登山靴は必要ありません。"]},{"id":"lunch","title":"昼食（各自負担）","preview":"昼食は南怡島のあと、12:15ごろに加平船着場周辺の地元レストランでとります。","content":["昼食は南怡島のあと、12:15ごろに加平船着場周辺の地元レストランでとります。","ここはタッカルビの本場です — 甘辛い鶏肉を鉄板で炒め、最後に残ったタレでご飯を炒めるのが定番です。マッククス（冷たいそば）が定番の相棒の一皿です。","予算は1人あたりおよそ₩10,000〜15,000。現金・カードとも通常使えますが、船着場近くの屋台は現金のみのことが多いです。","この地域はベジタリアン向けの選択肢が限られます — 朝のうちにガイドへお伝えいただければ、事前に店へ連絡します。"]},{"id":"cancellation","title":"キャンセル","preview":"ピックアップの24時間前まで無料でキャンセル可能です。","content":["ピックアップの24時間前まで無料でキャンセル可能です。","24時間以内のキャンセル：50%返金。","無断キャンセルまたはピックアップの見逃し：返金不可 — ただし、ピックアップ予定時刻から10分以内にAtoC Korea運営部門へご連絡いただければ、バスが予定より早く進んでいる場合は少々お待ちいただける場合があります。"]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"季節のご案内をご参照ください"},"tomorrow":{"temp":"—","label":"季節のご案内をご参照ください"},"_seasonalSummary":"Seoul + Gangwon: temperate four-season climate. Seoraksan is 5-7°C cooler than Seoul year-round. Hot humid summers (Jun-Aug), crisp cold winters (Dec-Feb), with prime seasons in spring (April cherry blossoms) and autumn (October-November foliage)."},"seasonalVariations":[{"season":"春（3〜5月）","description":"4月上旬は北漢江沿いの桜、その後は晨静苑の春のフェスティバルで数万本のチューリップが咲きます。プチフランスのパステルカラーの建物は、新緑を背にしたときが最も映えます。"},{"season":"夏（6〜8月）","description":"南怡島の並木道はしっかりと日陰をつくり、島はソウルよりはっきり涼しく感じられます。庭園は緑豊かですが暑く、日陰はほとんどありません — 水と日よけをお持ちください。7月の梅雨時は午後のにわか雨があります。"},{"season":"秋（9〜11月）","description":"このルートで最も強い季節です。南怡島のメタセコイアとイチョウの並木は10月下旬から11月中旬にかけて色づき、晨静苑では秋の菊の展示が行われます。需要のピークですので、お早めのご予約を。"},{"season":"冬（12〜2月）","description":"晨静苑のライティングフェスティバルが12月初旬から3月中旬ごろまで園内を照らし、その期間は夜まで開園します。雪の南怡島は、『冬のソナタ』のあの光景そのものです。谷は冷え込み、フェリーの甲板は吹きさらしですので、しっかりとした服装でお越しください。"}],"bookingTrustItems":[{"icon":"check-circle","title":"入場料すべて込み","description":"南怡島フェリー＋モーニングカームがセット","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600","body":"南怡島フェリー（₩19,000）とモーニングカーム（₩11,000）の入場料はツアー料金に含まれており、各スポットでのチケット購入は不要です。雪嶽山の入場料は無料（2023年5月廃止）。入場料の総節約額：約₩30,000。"},{"icon":"users","title":"公認英語ガイド付き","description":"韓国公認ツアーガイド","iconBg":"bg-pink-50/80","iconColor":"text-pink-600","body":"韓国観光公社認定の英語堪能なガイドが案内します。中国語対応ガイドは事前リクエストにて手配可能です。ガイドによる解説では、雪嶽山の新羅時代の寺院の歴史、南怡島の「冬のソナタ」にまつわる背景、そしてモーニングカームの創設者のストーリーをご紹介します。"},{"icon":"shield","title":"明瞭な料金体系","description":"隠れたショッピングストップなし","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","body":"高麗人参店への立ち寄りなし、免税店なし、コミッション目的のお土産店への寄り道なし。13時間の終日ツアーのすべての時間は、観光地での滞在か移動に充てられます。予約したとおりのご体験をお届けします。"}],"bookingSupportSteps":[{"timing":"即時","title":"即時確認","detail":"ピックアップ場所選択付き予約確認","description":"弘大（ホンデ）・明洞のピックアップ場所選択付き即時予約確認。"},{"timing":"前日","title":"ピックアップ詳細","detail":"WhatsApp／SMSにて正確なピックアップ場所と車両情報をお知らせ","description":"天気確認、コーチのナンバープレート、季節ごとのルートに関する注意事項（アチムコヨ樹木園ライティングフェスティバルの時間、雪岳山の紅葉ピーク時期など）を前日にお送りします。"},{"timing":"当日朝","title":"ピックアップ確認","detail":"出発10分前にピックアップ場所でガイドが確認対応","description":"ガイドは05:50よりスターバックス弘大8番出口前、06:20より明洞2番出口（ノースフェイス前）にてお待ちします。前夜にガイドとコーチの写真をWhatsAppへお送りします。"},{"timing":"ツアー中","title":"ツアー中サポート","detail":"各スポットでのガイドナレーション＋24時間対応オペレーションサポート","description":"ガイドは現地にて解説を行います。雪岳山の西暦652年・新羅時代の開創、ナミ島の1944年・清平ダム建設を起源とする歴史と2002年の「冬のソナタ」の舞台としての遺産、そしてアチムコヨ樹木園の1992年の構想と1996年の開園についてご説明します。"},{"timing":"終日の終わりに","title":"2か所の降車地点","detail":"明洞 約19:00 ／ 弘大 約19:30","description":"コーチは帰路、両ピックアップ地点に逆順で停車します。"},{"timing":"ツアー後","title":"レビュー＆フォローアップ","detail":"任意のツアー後レビュー","description":"ツアー後のフィードバックのお願いをお送りします。ソウル滞在中のレストランや観光スポットに関するご質問には当日中にお答えします。"}],"staticQuestions":[{"question":"入場料は本当にすべて含まれていますか？","answer":"はい — このルートの3か所の入場料はすべて含まれています。南怡島の₩19,000のナミナラ共和国ビザ料金（往復フェリー込み）、晨静苑の₩11,000、そしてプチフランスの₩12,000です。大人1名あたりおよそ₩42,000分を、並ぶことも、その場で払い直すこともなく済ませられます。ご自身でお支払いいただく主なものは昼食です。"},{"question":"南怡島と晨静苑を回る雪岳山ツアーと同じものですか？","answer":"いいえ。違いはおよそ3時間の走行時間です。雪岳山日帰りツアーは江原道の国立公園が加わるため、06:00発、走行5時間、13時間の一日になります。このツアーは加平の中で完結します — 07:30発、走行およそ3時間、そして山の代わりにプチフランスです。バスに乗る時間を抑えて庭園と島を楽しみたい方は、こちらをお選びください。"},{"question":"どのくらい歩きますか？","answer":"1日を通しておよそ5〜6 kmで、間にバス移動を挟んだ3か所に分かれています。登山も山頂も、長い階段もありません。南怡島は完全に平坦、晨静苑は緩やかな起伏、プチフランスは丘の小さな村です。普段の歩きやすい靴で十分です。"},{"question":"小さなお子さまや年配の方にも向いていますか？","answer":"はい。ソウル発の日帰りツアーの中では向いているほうです。どの立ち寄り先も平坦か緩やかな傾斜で、最も長い1区間の走行も約1.5時間、一日は19:00までに終わります。島を歩くのが大変な場合、南怡島では自転車と電動カートを借りられますし、晨静苑のメインの周回路はおおむねベビーカーで通行できます。唯一の留意点は一日の長さで、それでもドア・ツー・ドアで11時間かかります。"},{"question":"ナミナラ共和国のビザ料金とは何ですか？","answer":"南怡島の入場券のことです。島が2006年に文化観光のコンセプトとして「ナミナラ共和国」を宣言し、独自の国旗・切手・入国審査カウンターまで備えているため、ビザという体裁をとっています。実際には往復5分のフェリーを含む大人₩19,000の入場券で、本ツアーに含まれています。"},{"question":"プチフランスの隣のイタリアンビレッジにも行けますか？","answer":"この行程では行けません。ピノキオ＆ダ・ヴィンチ・イタリアンビレッジはプチフランスの真後ろの丘にあり、セット券（大人₩19,500）と、さらに1時間以上が必要です。本ツアーはプチフランスのみを含み、滞在は1時間です。イタリアンビレッジを重視される場合は、当社のプライベート加平ツアーで組み込むことができます。"},{"question":"雨が降ったらどうなりますか？","answer":"ツアーは運行します。3か所とも小雨なら問題ありません — 南怡島の並木道と庭園はどちらも濡れているときにこそ雰囲気があり、プチフランスにはサン＝テグジュペリ館やオルゴールハウスなどの屋内展示室があります。実際の天候リスクは、荒天で南怡島のフェリーが運休する場合だけで、そのときはガイドが他の2か所の滞在を延ばし、南怡島の入場料を返金します。"},{"question":"晨静苑のライティングフェスティバルは含まれていますか？","answer":"フェスティバルは別料金ではありません — 園内で行われており、含まれている入場料でご覧いただけます。ただしこれは日中の行程です。私たちが庭園にいるのは午後の早い時間なので、12月から3月のフェスティバル期間でも、照明が灯っていない状態をご覧いただくことになります。ライトアップされた庭園を優先されるのであれば、お知らせください。夜の選択肢をご案内します。"},{"question":"どの韓国ドラマがここで撮影されましたか？","answer":"南怡島は『冬のソナタ』（2002年）のロケ地で、メタセコイア並木は皆さんが立ちに来るあの場面です。プチフランスには『ベートーベン・ウイルス』（2008年）、『個人の趣向』（2010年）、『シークレット・ガーデン』（2010年）、『星から来たあなた』（2013〜14年）などがあります。晨静苑も『雲が描いた月明り』などの撮影地として使われています。"},{"question":"ソウルには何時に戻りますか？","answer":"明洞駅に18:30ごろ、弘大入口駅に19:00ごろです。どちらも地下鉄の乗換駅です。金曜の夕方や日曜の帰路は、市内に近づくあたりで20〜40分ほど余計にかかることがあります — その日の見込みはガイドが車内でお伝えします。夜の時間を空けておけるよう、意図的に早めの設定にしています。"},{"question":"昼食は含まれていますか？","answer":"いいえ。加平船着場周辺のレストランで1時間停車し、お好きなものを注文してお支払いいただきます。目安は₩10,000〜15,000です。ここはタッカルビ — 甘辛い鶏肉を鉄板で炒める料理 — の本場で、通常はマッククスと一緒に食べます。ベジタリアン向けの選択肢は限られますので、朝のうちにガイドへお伝えください。事前に店へ連絡します。"},{"question":"ガイドは同行しますか。言語は何ですか？","answer":"はい — 有資格の英語ガイドが一日を通してバスに同行します。3日前までにご予約いただければ、中国語ガイドの手配も可能です。各スポットの見学は基本的に自由行動で、ガイドは入場手続き、時間管理、案内、通訳を担い、絶え間ない解説を行うわけではありません。"}],"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]},"sticky_booking_bar":{"note":"ご希望の日付と人数を選択して、空き状況をご確認のうえ、ご予約を完了してください。","price":{"amountLabel":"59","currency":"USD","per":"person","salePriceUsd":59}},"pickup_dropoff":{"primary":{"name":"スターバックス 弘大入口駅 8番出口","address":"ソウル市麻浦区楊花路（弘大入口駅8番出口のスターバックス前）","time":"07:30 乗車 ／ 19:00 降車","instructions":"弘大入口駅8番出口を上がってすぐのスターバックス店舗前でガイドとお会いください。AtoC Koreaの看板と、乗車列に停まっているバスが目印です。"},"alternates":[{"name":"明洞駅 2番出口（ノースフェイス旗艦店）","address":"ソウル市中区退渓路（明洞駅2番出口のノースフェイス旗艦店）","time":"08:00 乗車 ／ 18:30 降車","instructions":"明洞駅2番出口を上がったところにあるノースフェイス旗艦店の前でガイドとお会いください。"}]},"matching_profile":{"profile_version":1,"is_active":true,"product_id":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","product_type":"bus","route_type":"fixed_route","destination_region":"seoul_gangwon","region_type":"gangwon_seoraksan","vehicle_type":"large_coach","duration_hours":11,"region_tags":["seoul_mapo","seoul_jung","gangwon_sokcho","gyeonggi_gapyeong"