it":0.15,"seasonal_fit":1,"winter_lighting_festival_fit":1,"autumn_foliage_fit":1,"china_mainland_market_fit":0.85,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":1,"se_asia_market_fit":1,"us_market_fit":0.95,"europe_market_fit":0.95,"australia_market_fit":0.95,"japan_market_fit":1,"first_time_korea_fit":1,"seoul_day_trip_fit":1,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true},"matching_metadata":{"primary_themes":["gapyeong","seoul_day_trip","k_drama_filming","themed_garden","river_island","french_village"],"secondary_themes":["winter_sonata","metasequoia_lane","lighting_festival","photo_spots","autumn_foliage","first_time_korea"],"best_for":["first_time_korea","couples","photo_lovers","families","k_drama_fans","seniors"],"not_recommended_for":["hikers_seeking_mountains","nightlife_focused_travelers","travelers_wanting_a_short_half_day"],"anchor_pois":["Nami Island","The Garden of Morning Calm","Petite France"],"anchor_poi_keys":["nami_island","garden_of_morning_calm","petite_france"],"competing_products":["seoul-seoraksan-nami-island-morning-calm-day-tour","seoul-private-nami-morning-calm-petite-france","pocheon-sanjeong-lake-herb-island-art-valley"],"reviews_attribution":"New product (2026-08) — no imported reviews; rating starts at 0.","unesco_fit_note":"No UNESCO property on this route. Cultural weight is popular-culture and horticultural: Winter Sonata''s metasequoia lane on Nami Island, a 330,000 m² private arboretum, and a licensed Le Petit Prince village."},"itinerary_variants":[],"_publication":{"schema_version":"v4_canonical","created":"2026-08-04","last_modified":"2026-08-04","version_history":["v1_authored_2026_08_04"],"fix_passes":{"v1_authored_2026_08_04":"New product (owner instruction 2026-08-04). The Gapyeong trio as a join-in-group coach day tour — the join-in counterpart to the existing private seoul-private-nami-morning-calm-petite-france. Donor A (seoul-seoraksan-nami-island-morning-calm-day-tour) supplied the KB-verified Nami Island and Garden of Morning Calm stop bodies plus Seoul-region weather/trust/support blocks and the two-point Seoul pickup; donor B (seoul-private-nami-morning-calm-petite-france) supplied the Petite France stop body. Pickup, lunch, return and all product-level copy authored fresh in 6 locales (scripts/seoul-gapyeong-content/) with de/fr/it/ru staged. Stop admission/hours re-verified 2026-08-04 against operator and KTO sources. matching_profile derived from donor A with the mountain axes zeroed and garden/K-drama axes raised — full KB calibration pending."}},"page_sections":[]}'::jsonb
